import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { _validateIpcRequest, _dispatchDesktopIpc, startDesktop } from '../../src/interface/main.mjs';
import { WB_OPERATIONS, workbenchDTO, boundPlan } from '../../src/models/workbench.mjs';
const role = process.env.LEGION_DESKTOP_TEST_ROLE ?? 'DesktopEngineer';
assert.ok(['DesktopEngineer', 'ProjectManager', 'Reviewer', 'Tester'].includes(role));
// This suite has no generated filesystem effects; Pipeline effects use the same caller role enum.
const projectId = 'a'.repeat(64);
const documentUrl = 'file:///D:/owned/index.html'; const frame = { url: documentUrl }; const contents = { mainFrame: frame }; const window = { webContents: contents, isDestroyed: () => false }; const event = { sender: contents, senderFrame: frame };
const plan = boundPlan({ goal: '精确修改', roles: [{ id: 'Builder', name: '开发', purpose: '修改文件', profileId: 'p1' }], tasks: [{ id: 'task1', title: '修改文件', roleId: 'Builder', profileId: 'p1', dependsOn: [], writeSet: ['a.txt'], instruction: '修改' }] }, { projectId, organizationVersion: 'customer-v1', revision: 1, profileBindings: [{ profileId: 'p1', profileVersion: 'b'.repeat(64), contextSnapshotDigest: 'c'.repeat(64) }], contextSnapshotDigest: 'd'.repeat(64) });
const dto = { ...workbenchDTO({ profiles: [], assignments: [], projects: [], history: { messages: [] } }), currentProject: { id: projectId, name: '项目', organizationVersion: 'customer-v1', hasManager: true }, roles: [{ id: 'ProjectManager', name: '项目管理', purpose: '澄清', profileId: 'p1' }, ...plan.roles], plan };

test('IPC exact sender/frame/URL, PM-only input and unsupported execution reject before Pipeline', async () => {
  const calls = []; const pipeline = { getState: async (input) => { calls.push(input); return { ok: true, value: dto }; } };
  const bad = [[{ ...event, sender: {} }, window, documentUrl, 'getState', {}], [{ ...event, senderFrame: { url: documentUrl } }, window, documentUrl, 'getState', {}], [event, { ...window, isDestroyed: () => true }, documentUrl, 'getState', {}], [event, window, 'file:///other.html', 'getState', {}], [event, window, documentUrl, 'getState', { workspaceRoot: 'D:/private' }], [event, window, documentUrl, 'chooseProject', { path: 'D:/private' }], [event, window, documentUrl, 'sendMessage', { projectId, roleId: 'Builder', text: '直接聊' }], [event, window, documentUrl, 'confirmPlan', { projectId, planDigest: plan.planDigest, roleId: 'Builder' }], [event, window, documentUrl, 'startAgent', {}], [event, window, documentUrl, 'selectContext', { projectId, resources: ['../outside'] }]];
  for (const args of bad) assert.equal((await _dispatchDesktopIpc(...args, pipeline)).ok, false);
  assert.deepEqual(calls, []); const accepted = await _dispatchDesktopIpc(event, window, documentUrl, 'getState', { force: true }, pipeline); assert.equal(accepted.ok, true); assert.deepEqual(calls, [{ force: true }]); assert.equal(accepted.value.currentProject.id, projectId); assert.equal(accepted.value.plan.planDigest, plan.planDigest); assert.equal(_validateIpcRequest(null, window, documentUrl, 'getState').error.code, 'unauthorized_sender');
});
test('all operation mappings and output reconstruction preserve plan/current project, omit private fields and raw errors', async () => {
  const calls = []; const pipeline = {};
  for (const operation of WB_OPERATIONS) pipeline[operation] = async (input) => { calls.push([operation, input]); if (operation === 'testConnection') return { ok: true, value: { status: 'success', latencyMs: 12, key: 'private' } }; if (operation === 'cancelProbe') return { ok: true, value: { secret: 'private' } }; return { ok: true, value: { ...dto, key: 'private', workspaceIdentity: 'private' } }; };
  const inputs = { getState: {}, refreshProject: {}, setDefaultProfile: { profileId: 'p1' }, saveProfile: { name: '连接', protocol: 'openai-completions', provider: 'local', modelId: 'm', baseUrl: 'http://localhost:1234', keyAction: 'keep', apiKey: '' }, deleteProfile: { id: 'p1' }, assignProfile: { roleId: 'ProjectManager', profileId: 'p1' }, sendMessage: { projectId, roleId: 'ProjectManager', text: '需求' }, selectContext: { projectId, resources: ['a.txt'] }, confirmPlan: { projectId, planDigest: plan.planDigest }, cancelTurn: { projectId, turnId: 'turn1' }, stopExecution: { projectId }, testConnection: { profileId: 'p1' }, cancelProbe: { probeId: 'probe1' } };
  for (const [operation, input] of Object.entries(inputs)) { const result = await _dispatchDesktopIpc(event, window, documentUrl, operation, input, pipeline); assert.equal(result.ok, true, operation); assert.equal(JSON.stringify(result).includes('private'), false); if (operation === 'cancelProbe') assert.equal(result.value, null); else if (operation === 'testConnection') assert.equal(result.value.latencyMs, 12); else assert.deepEqual(result.value, dto); }
  assert.equal(calls.length, 13); assert.deepEqual(calls.find((item) => item[0] === 'sendMessage')[1], inputs.sendMessage); pipeline.getState = async () => ({ ok: false, error: { code: 'plan_changed', message: 'Bearer private', stack: 'private' } }); const failed = await _dispatchDesktopIpc(event, window, documentUrl, 'getState', {}, pipeline); assert.equal(failed.error.code, 'plan_changed'); assert.equal(JSON.stringify(failed).includes('private'), false); pipeline.getState = async () => { throw new Error('raw SDK/key'); }; assert.equal((await _dispatchDesktopIpc(event, window, documentUrl, 'getState', {}, pipeline)).error.code, 'internal_error');
});
test('startup inert/options finite; narrow preload, Node-off renderer and fixed CSP', async () => {
  await assert.rejects(startDesktop({ services: {} })); await assert.rejects(startDesktop({ initialWorkspace: '../unsafe' })); await assert.rejects(startDesktop({ show: 'true' }));
  const main = await readFile(new URL('../../src/interface/main.mjs', import.meta.url), 'utf8'); const preload = await readFile(new URL('../../src/interface/preload.cjs', import.meta.url), 'utf8'); const html = await readFile(new URL('../../src/interface/index.html', import.meta.url), 'utf8'); assert.equal(/services\/|providers\/|kernel\//u.test(main), false); assert.match(main, /nodeIntegration: false, contextIsolation: true, sandbox: true/u); assert.equal(/ipcRenderer\.on|sendSync|require\(['"]node:/u.test(preload), false); assert.deepEqual([...preload.matchAll(/invoke\('legion-desktop:([^']+)'/gu)].map((match) => match[1]).sort(), [...WB_OPERATIONS].sort()); assert.match(html, /connect-src 'none'; frame-src 'none'; object-src 'none'/u);
});
